pages/custom/product/product-layout-4:
---
product:
    videos:
        limit: {{theme_settings.productpage_videos_count}}
    reviews:
        limit: {{theme_settings.productpage_reviews_count}}
    related_products:
        limit: {{theme_settings.productpage_related_products_count}}
    similar_by_views:
        limit: {{theme_settings.productpage_similar_by_views_count}}
products:
    featured:
        limit: 6
---
{{#partial "page"}}
<div class="themevale_breadcrumb">
    {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}
</div>
<div class="page"> 
    <aside class="page-sidebar">
        {{> components/products/product-sidebar}}
    </aside>
    <main class="page-content product-layout-3" id="product-listing-container">
        {{#each product.shipping_messages}}
            {{> components/common/alert-info message}}
        {{/each}}
        <div class="themevale_sidebar-mobile-wrapper">
            <div class="item item-iconSidebar text-left">
                <div class="themevale_sidebar-mobile">
                    <span class='text'>sidebar:</span>
                    <svg class="icon"><use xlink:href='#sidebar'></use></svg>
                </div>
            </div>
        </div>
        <div itemscope itemtype="http://schema.org/Product">
            {{> components/products/product-view-3 schema=true}}
            {{> components/themevale/product/product-description-3 schema=true}}
        </div>
    </main>
    <div class="clearfix"></div>
    {{#all settings.show_product_reviews}}
        {{> components/products/reviews reviews=product.reviews product=product urls=urls}}
    {{/all}}
    {{#if product.similar_by_views}}
        <section class="toggle productSimilar" id="product-similar" data-product-reviews>
            <div class="toggle-title">
                <h4 class="page-heading">{{lang 'products.similar_by_views'}}</h4>
            </div>
            <div class="toggle-content is-open" id="productSimilar-content" aria-hidden="false">
                {{> components/products/carousel products=product.similar_by_views columns=5 arrows=true dots=true}}
            </div>
        </section>
    {{/if}}
</div>
{{/partial}}
{{> layout/base}}

components/themevale/sidebar/featured-pr:
{{#if theme_settings.sidebar_featured-products}} 
    <div id="featured-products" class="sidebarBlock">
        <h5 class="sidebarBlock-heading">{{theme_settings.sidebar_featured-products-title}} </h5>
        <div class="sidebarBlock-content productCarousel"
            data-slick='{
                "arrows": true,
                "dots": true,
                "autoplay": true,
                "infinite": true,
                "slidesToShow": 1,
                "slidesToScroll": 1,
                "nextArrow": "<svg class=&apos;slick-next slick-arrow&apos;><use xlink:href=&apos;#slick-arrow-next&apos;></use></svg>", 
                "prevArrow": "<svg class=&apos;slick-prev slick-arrow&apos;><use xlink:href=&apos;#slick-arrow-prev&apos;></use></svg>"
            }'>
            {{#each products}}
                <div class="productCarousel-slide">
                    {{> components/products/card-sidebar theme_settings=../theme_settings customer=../customer show_rating=../settings.show_product_rating show_wishlist=../settings.show_wishlist}}
                </div>
            {{/each}}
        </div>
    </div>
{{/if}}

components/themevale/sidebar/side-all-ca:
{{#if theme_settings.sidebar_allcategories}} 
    <div class="sidebarBlock" id="sideAllCategories">
        <h5 class="sidebarBlock-heading">{{theme_settings.sidebar_allcategories-title}} </h5>
        {{#if categories}}
        <ul class="all-categories-list">
            {{#each categories}}
            <li class="navPages-item">
                {{#if children}}
                    <a class="navPages-action has-subMenu" href="{{url}}">{{name}}</a>
                    <i class="icon-arrow"><svg><use xlink:href="#slick-arrow-next"/></svg></i>
                    <ul class="dropdown-category-list navPages-level-2">
                        {{#each children}}
                            {{> components/themevale/sidebar/sub-categories}}
                        {{/each}}
                    </ul>
                {{else}}
                    <a class="navPages-action" href="{{url}}">{{name}}</a>
                {{/if}}
            </li>
            {{/each}}
        </ul>
        {{/if}}
    </div>
{{/if}}

