                <span id="247commercenonsale"  data-product-non-sale-price-with-tax class="price price--non-sale">
                    {{price.non_sale_price_with_tax.formatted}}
                </span>
            </div>
            <div class="price-section price-section--withTax" {{#if schema_org}}itemprop="offers" itemscope itemtype="http://schema.org/Offer"{{/if}} style="margin-bottom:8px;">
                <span data-product-price-with-tax id="247commercesale" class="price price--withTax">{{price.with_tax.formatted}} </span>
                {{#if schema_org}}
                    <meta itemprop="availability" content="{{product.availability}}">
                    <meta itemprop="itemCondition" itemtype="http://schema.org/OfferItemCondition" content="http://schema.org/{{product.condition}}Condition">
